#include <bit>
#include <cstdint>

std::uint32_t bitsOf(float value)
{
    return std::bit_cast<std::uint32_t>(value);
}

bool isNegative(float value)
{
    return (std::bit_cast<std::uint32_t>(value) >> 31) != 0;
}
